//! Embeds the app icon (assets/slate.ico, regenerated by
//! tools/generate_icon.py) as the Windows .exe icon resource.

fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed=assets/slate.ico");
    #[cfg(windows)]
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows") {
        let mut resource = winresource::WindowsResource::new();
        // Resource id 1: the shell's .exe icon, also loaded by id for the
        // tray icon in src/resident.rs.
        resource.set_icon_with_id("assets/slate.ico", "1");
        if let Err(err) = resource.compile() {
            println!("cargo:warning=could not embed the app icon: {err}");
        }
    }
}
